import re
def has_limit(sql):
    return bool(re.search(r"\blimit\s+\d+", sql, re.I))
def only_select(sql):
    s = sql.strip().rstrip(";")
    return ";" not in s and bool(re.match(r"^(select|with)\b", s, re.I))
for q in ["SELECT * FROM orders", "select 1; drop table x", "WITH a AS (SELECT 1) SELECT * FROM a LIMIT 5"]:
    print(only_select(q), has_limit(q))

def is_safe(sql):
    return sql.strip().lower().startswith("select")

